import type { ListBooksUseCase } from '../../../application/catalog/ListBooksUseCase';
import type { RegisterBookUseCase } from '../../../application/catalog/RegisterBookUseCase';
import type { Book } from '../../../domain/catalog/Book';
import { errorResponse, field } from './http';
import type { HttpRequest, HttpResponse } from './http';

const toJson = (b: Book) => ({ isbn: b.isbn.value, title: b.title, author: b.author, copies: b.copies });

/** POST /books, GET /books */
export class BookController {
  constructor(
    private readonly registerBook: RegisterBookUseCase,
    private readonly listBooks: ListBooksUseCase,
  ) {}

  async register(req: HttpRequest): Promise<HttpResponse> {
    try {
      const book = await this.registerBook.execute({
        isbn: String(field(req.body, 'isbn') ?? ''),
        title: String(field(req.body, 'title') ?? ''),
        author: String(field(req.body, 'author') ?? ''),
        copies: Number(field(req.body, 'copies') ?? 1),
      });
      return { status: 201, body: toJson(book) };
    } catch (err) {
      return errorResponse(err);
    }
  }

  async list(_req: HttpRequest): Promise<HttpResponse> {
    const books = await this.listBooks.execute();
    return { status: 200, body: books.map(toJson) };
  }
}

import { DomainError } from '../../../domain/catalog/errors';

/** The minimal HTTP shape the inbound adapters speak; a real server would map its own request to this. */
export interface HttpRequest {
  readonly method: 'GET' | 'POST';
  readonly path: string;
  readonly params?: Readonly<Record<string, string>>;
  readonly query?: Readonly<Record<string, string>>;
  readonly body?: unknown;
}

export interface HttpResponse {
  readonly status: number;
  readonly body: unknown;
}

const STATUS_BY_CODE: Readonly<Record<string, number>> = {
  NOT_FOUND: 404,
  DUPLICATE_BOOK: 409,
};

/** Domain errors become 4xx answers; anything else is a 500 without internals. */
export function errorResponse(err: unknown): HttpResponse {
  if (err instanceof DomainError) {
    return { status: STATUS_BY_CODE[err.code] ?? 400, body: { error: err.code, message: err.message } };
  }
  return { status: 500, body: { error: 'INTERNAL', message: 'unexpected error' } };
}

export function field(body: unknown, name: string): unknown {
  return typeof body === 'object' && body !== null ? (body as Record<string, unknown>)[name] : undefined;
}

import type { BookRepository } from '../../../application/ports/BookRepository';
import type { Book } from '../../../domain/catalog/Book';
import type { Isbn } from '../../../domain/catalog/Isbn';

export class InMemoryBookRepository implements BookRepository {
  private readonly byIsbn = new Map<string, Book>();

  async save(book: Book): Promise<void> {
    this.byIsbn.set(book.isbn.value, book);
  }

  async findByIsbn(isbn: Isbn): Promise<Book | undefined> {
    return this.byIsbn.get(isbn.value);
  }

  async findAll(): Promise<Book[]> {
    return [...this.byIsbn.values()];
  }
}

import type { Book } from '../../domain/catalog/Book';
import type { BookRepository } from '../ports/BookRepository';

export class ListBooksUseCase {
  constructor(private readonly books: BookRepository) {}

  async execute(): Promise<Book[]> {
    const all = await this.books.findAll();
    return [...all].sort((a, b) => a.title.localeCompare(b.title));
  }
}

import { Book } from '../../domain/catalog/Book';
import { DuplicateBookError } from '../../domain/catalog/errors';
import { Isbn } from '../../domain/catalog/Isbn';
import type { BookRepository } from '../ports/BookRepository';

export interface RegisterBookCommand {
  readonly isbn: string;
  readonly title: string;
  readonly author: string;
  readonly copies: number;
}

export class RegisterBookUseCase {
  constructor(private readonly books: BookRepository) {}

  async execute(cmd: RegisterBookCommand): Promise<Book> {
    const isbn = Isbn.of(cmd.isbn);
    if ((await this.books.findByIsbn(isbn)) !== undefined) throw new DuplicateBookError(isbn.value);
    const book = Book.register(isbn, cmd.title, cmd.author, cmd.copies);
    await this.books.save(book);
    return book;
  }
}

import type { Book } from '../../domain/catalog/Book';
import type { Isbn } from '../../domain/catalog/Isbn';

/** Outbound port: where books are kept. */
export interface BookRepository {
  save(book: Book): Promise<void>;
  findByIsbn(isbn: Isbn): Promise<Book | undefined>;
  findAll(): Promise<Book[]>;
}

import { BookController } from '../adapters/inbound/http/BookController';
import { InMemoryBookRepository } from '../adapters/outbound/persistence/InMemoryBookRepository';
import { ListBooksUseCase } from '../application/catalog/ListBooksUseCase';
import { RegisterBookUseCase } from '../application/catalog/RegisterBookUseCase';

/** Composition root: the only place that instantiates adapters. */
export function createContainer() {
  const books = new InMemoryBookRepository();
  return {
    bookController: new BookController(new RegisterBookUseCase(books), new ListBooksUseCase(books)),
  };
}

export type Container = ReturnType<typeof createContainer>;

import { InvalidBookError } from './errors';
import { Isbn } from './Isbn';

/** A title the library owns, with the number of physical copies. */
export class Book {
  private constructor(
    readonly isbn: Isbn,
    readonly title: string,
    readonly author: string,
    readonly copies: number,
  ) {}

  static register(isbn: Isbn, title: string, author: string, copies: number): Book {
    if (title.trim() === '') throw new InvalidBookError('title is required');
    if (author.trim() === '') throw new InvalidBookError('author is required');
    if (!Number.isInteger(copies) || copies < 1) throw new InvalidBookError('copies must be a whole number of at least 1');
    return new Book(isbn, title.trim(), author.trim(), copies);
  }
}

import { InvalidIsbnError } from './errors';

/** An ISBN-13 whose check digit is valid. Immutable. */
export class Isbn {
  private constructor(readonly value: string) {}

  static of(raw: string): Isbn {
    const digits = raw.replace(/[-\s]/g, '');
    if (!/^\d{13}$/.test(digits)) throw new InvalidIsbnError(raw);
    const sum = [...digits.slice(0, 12)].reduce((acc, d, i) => acc + Number(d) * (i % 2 === 0 ? 1 : 3), 0);
    const check = (10 - (sum % 10)) % 10;
    if (check !== Number(digits[12])) throw new InvalidIsbnError(raw);
    return new Isbn(digits);
  }

  equals(other: Isbn): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

/** A business rule was broken; the message is safe to show to the caller. */
export class DomainError extends Error {
  constructor(readonly code: string, message: string) {
    super(message);
    this.name = 'DomainError';
  }
}

export class InvalidIsbnError extends DomainError {
  constructor(value: string) {
    super('INVALID_ISBN', `"${value}" is not a valid ISBN-13`);
  }
}

export class InvalidBookError extends DomainError {
  constructor(reason: string) {
    super('INVALID_BOOK', reason);
  }
}

export class DuplicateBookError extends DomainError {
  constructor(isbn: string) {
    super('DUPLICATE_BOOK', `a book with ISBN ${isbn} is already registered`);
  }
}

export class NotFoundError extends DomainError {
  constructor(what: string) {
    super('NOT_FOUND', `${what} not found`);
  }
}

