import type { GetMemberUseCase } from '../../../application/membership/GetMemberUseCase';
import type { RegisterMemberUseCase } from '../../../application/membership/RegisterMemberUseCase';
import type { Member } from '../../../domain/membership/Member';
import { errorResponse, field } from './http';
import type { HttpRequest, HttpResponse } from './http';

const toJson = (m: Member) => ({ id: m.id, name: m.name, email: m.email.value, borrowingLimit: m.borrowingLimit });

/** POST /members, GET /members/:id */
export class MemberController {
  constructor(
    private readonly registerMember: RegisterMemberUseCase,
    private readonly getMember: GetMemberUseCase,
  ) {}

  async register(req: HttpRequest): Promise<HttpResponse> {
    try {
      const member = await this.registerMember.execute({
        name: String(field(req.body, 'name') ?? ''),
        email: String(field(req.body, 'email') ?? ''),
      });
      return { status: 201, body: toJson(member) };
    } catch (err) {
      return errorResponse(err);
    }
  }

  async get(req: HttpRequest): Promise<HttpResponse> {
    try {
      return { status: 200, body: toJson(await this.getMember.execute(req.params?.id ?? '')) };
    } catch (err) {
      return errorResponse(err);
    }
  }
}

import { DomainError } from '../../../domain/catalog/errors';

/** The minimal HTTP shape the inbound adapters speak; a real server would map its own request to this. */
export interface HttpRequest {
  readonly method: 'GET' | 'POST';
  readonly path: string;
  readonly params?: Readonly<Record<string, string>>;
  readonly query?: Readonly<Record<string, string>>;
  readonly body?: unknown;
}

export interface HttpResponse {
  readonly status: number;
  readonly body: unknown;
}

const STATUS_BY_CODE: Readonly<Record<string, number>> = {
  NOT_FOUND: 404,
  DUPLICATE_BOOK: 409,
  DUPLICATE_MEMBER: 409,
};

/** Domain errors become 4xx answers; anything else is a 500 without internals. */
export function errorResponse(err: unknown): HttpResponse {
  if (err instanceof DomainError) {
    return { status: STATUS_BY_CODE[err.code] ?? 400, body: { error: err.code, message: err.message } };
  }
  return { status: 500, body: { error: 'INTERNAL', message: 'unexpected error' } };
}

export function field(body: unknown, name: string): unknown {
  return typeof body === 'object' && body !== null ? (body as Record<string, unknown>)[name] : undefined;
}

import type { MemberRepository } from '../../../application/ports/MemberRepository';
import type { Email } from '../../../domain/membership/Email';
import type { Member } from '../../../domain/membership/Member';

export class InMemoryMemberRepository implements MemberRepository {
  private readonly byId = new Map<string, Member>();
  private seq = 0;

  async nextId(): Promise<string> {
    this.seq += 1;
    return `m-${String(this.seq)}`;
  }

  async save(member: Member): Promise<void> {
    this.byId.set(member.id, member);
  }

  async findById(id: string): Promise<Member | undefined> {
    return this.byId.get(id);
  }

  async findByEmail(email: Email): Promise<Member | undefined> {
    return [...this.byId.values()].find((m) => m.email.value === email.value);
  }
}

import { NotFoundError } from '../../domain/catalog/errors';
import type { Member } from '../../domain/membership/Member';
import type { MemberRepository } from '../ports/MemberRepository';

export class GetMemberUseCase {
  constructor(private readonly members: MemberRepository) {}

  async execute(id: string): Promise<Member> {
    const member = await this.members.findById(id);
    if (member === undefined) throw new NotFoundError(`member ${id}`);
    return member;
  }
}

import { Email } from '../../domain/membership/Email';
import { DuplicateMemberError, Member } from '../../domain/membership/Member';
import type { MemberRepository } from '../ports/MemberRepository';

export class RegisterMemberUseCase {
  constructor(private readonly members: MemberRepository) {}

  async execute(cmd: { readonly name: string; readonly email: string }): Promise<Member> {
    const email = Email.of(cmd.email);
    if ((await this.members.findByEmail(email)) !== undefined) throw new DuplicateMemberError(email.value);
    const member = Member.register(await this.members.nextId(), cmd.name, email);
    await this.members.save(member);
    return member;
  }
}

import type { Email } from '../../domain/membership/Email';
import type { Member } from '../../domain/membership/Member';

/** Outbound port: where members are kept. */
export interface MemberRepository {
  nextId(): Promise<string>;
  save(member: Member): Promise<void>;
  findById(id: string): Promise<Member | undefined>;
  findByEmail(email: Email): Promise<Member | undefined>;
}

import { BookController } from '../adapters/inbound/http/BookController';
import { MemberController } from '../adapters/inbound/http/MemberController';
import { InMemoryBookRepository } from '../adapters/outbound/persistence/InMemoryBookRepository';
import { InMemoryMemberRepository } from '../adapters/outbound/persistence/InMemoryMemberRepository';
import { ListBooksUseCase } from '../application/catalog/ListBooksUseCase';
import { RegisterBookUseCase } from '../application/catalog/RegisterBookUseCase';
import { GetMemberUseCase } from '../application/membership/GetMemberUseCase';
import { RegisterMemberUseCase } from '../application/membership/RegisterMemberUseCase';

/** Composition root: the only place that instantiates adapters. */
export function createContainer() {
  const books = new InMemoryBookRepository();
  const members = new InMemoryMemberRepository();
  return {
    bookController: new BookController(new RegisterBookUseCase(books), new ListBooksUseCase(books)),
    memberController: new MemberController(new RegisterMemberUseCase(members), new GetMemberUseCase(members)),
  };
}

export type Container = ReturnType<typeof createContainer>;

import { DomainError } from '../catalog/errors';

export class InvalidEmailError extends DomainError {
  constructor(value: string) {
    super('INVALID_EMAIL', `"${value}" is not a valid e-mail address`);
  }
}

/** A lower-cased e-mail address. Immutable. */
export class Email {
  private constructor(readonly value: string) {}

  static of(raw: string): Email {
    const v = raw.trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) throw new InvalidEmailError(raw);
    return new Email(v);
  }
}

import { DomainError } from '../catalog/errors';
import type { Email } from './Email';

export const DEFAULT_BORROWING_LIMIT = 3;

export class DuplicateMemberError extends DomainError {
  constructor(email: string) {
    super('DUPLICATE_MEMBER', `a member with e-mail ${email} is already registered`);
  }
