import type { LendBookUseCase } from '../../../application/lending/LendBookUseCase';
import type { ListMemberLoansUseCase } from '../../../application/lending/ListMemberLoansUseCase';
import type { ReturnBookUseCase } from '../../../application/lending/ReturnBookUseCase';
import type { Loan } from '../../../domain/lending/Loan';
import { errorResponse, field } from './http';
import type { HttpRequest, HttpResponse } from './http';

const day = (d: Date | undefined) => (d === undefined ? null : d.toISOString().slice(0, 10));
const toJson = (l: Loan) => ({
  id: l.id,
  isbn: l.isbn.value,
  memberId: l.memberId,
  loanedAt: day(l.loanedAt),
  dueAt: day(l.dueAt),
  returnedAt: day(l.returnedAt),
});

/** POST /loans, POST /loans/:id/return, GET /members/:id/loans */
export class LoanController {
  constructor(
    private readonly lendBook: LendBookUseCase,
    private readonly returnBook: ReturnBookUseCase,
    private readonly listMemberLoans: ListMemberLoansUseCase,
  ) {}

  async lend(req: HttpRequest): Promise<HttpResponse> {
    try {
      const loan = await this.lendBook.execute({
        isbn: String(field(req.body, 'isbn') ?? ''),
        memberId: String(field(req.body, 'memberId') ?? ''),
      });
      return { status: 201, body: toJson(loan) };
    } catch (err) {
      return errorResponse(err);
    }
  }

  async return(req: HttpRequest): Promise<HttpResponse> {
    try {
      return { status: 200, body: toJson(await this.returnBook.execute(req.params?.id ?? '')) };
    } catch (err) {
      return errorResponse(err);
    }
  }

  async listForMember(req: HttpRequest): Promise<HttpResponse> {
    const loans = await this.listMemberLoans.execute(req.params?.id ?? '');
    return { status: 200, body: loans.map(toJson) };
  }
}

import { DomainError } from '../../../domain/catalog/errors';

/** The minimal HTTP shape the inbound adapters speak; a real server would map its own request to this. */
export interface HttpRequest {
  readonly method: 'GET' | 'POST';
  readonly path: string;
  readonly params?: Readonly<Record<string, string>>;
  readonly query?: Readonly<Record<string, string>>;
  readonly body?: unknown;
}

export interface HttpResponse {
  readonly status: number;
  readonly body: unknown;
}

const STATUS_BY_CODE: Readonly<Record<string, number>> = {
  NOT_FOUND: 404,
  DUPLICATE_BOOK: 409,
  DUPLICATE_MEMBER: 409,
  NO_COPY_AVAILABLE: 409,
  BORROWING_LIMIT: 409,
  ALREADY_RETURNED: 409,
};

/** Domain errors become 4xx answers; anything else is a 500 without internals. */
export function errorResponse(err: unknown): HttpResponse {
  if (err instanceof DomainError) {
    return { status: STATUS_BY_CODE[err.code] ?? 400, body: { error: err.code, message: err.message } };
  }
  return { status: 500, body: { error: 'INTERNAL', message: 'unexpected error' } };
}

export function field(body: unknown, name: string): unknown {
  return typeof body === 'object' && body !== null ? (body as Record<string, unknown>)[name] : undefined;
}

import type { LoanRepository } from '../../../application/ports/LoanRepository';
import type { Isbn } from '../../../domain/catalog/Isbn';
import type { Loan } from '../../../domain/lending/Loan';

export class InMemoryLoanRepository implements LoanRepository {
  private readonly byId = new Map<string, Loan>();
  private seq = 0;

  async nextId(): Promise<string> {
    this.seq += 1;
    return `l-${String(this.seq)}`;
  }

  async save(loan: Loan): Promise<void> {
    this.byId.set(loan.id, loan);
  }

  async findById(id: string): Promise<Loan | undefined> {
    return this.byId.get(id);
  }

  async findOpenByMember(memberId: string): Promise<Loan[]> {
    return this.all().filter((l) => l.isOpen && l.memberId === memberId);
  }

  async countOpenByIsbn(isbn: Isbn): Promise<number> {
    return this.all().filter((l) => l.isOpen && l.isbn.value === isbn.value).length;
  }

  async countOpenByMember(memberId: string): Promise<number> {
    return (await this.findOpenByMember(memberId)).length;
  }

  /** Every loan, open or returned. */
  all(): Loan[] {
    return [...this.byId.values()];
  }
}

import { NotFoundError } from '../../domain/catalog/errors';
import { Isbn } from '../../domain/catalog/Isbn';
import { BorrowingLimitError, Loan, NoCopyAvailableError } from '../../domain/lending/Loan';
import type { BookRepository } from '../ports/BookRepository';
import type { LoanRepository } from '../ports/LoanRepository';
import type { MemberRepository } from '../ports/MemberRepository';

export class LendBookUseCase {
  constructor(
    private readonly books: BookRepository,
    private readonly members: MemberRepository,
    private readonly loans: LoanRepository,
  ) {}

  async execute(cmd: { readonly isbn: string; readonly memberId: string }): Promise<Loan> {
    const isbn = Isbn.of(cmd.isbn);
    const book = await this.books.findByIsbn(isbn);
    if (book === undefined) throw new NotFoundError(`book ${isbn.value}`);
    const member = await this.members.findById(cmd.memberId);
    if (member === undefined) throw new NotFoundError(`member ${cmd.memberId}`);
    if ((await this.loans.countOpenByIsbn(isbn)) >= book.copies) throw new NoCopyAvailableError(isbn.value);
    if ((await this.loans.countOpenByMember(member.id)) >= member.borrowingLimit) {
      throw new BorrowingLimitError(member.id, member.borrowingLimit);
    }
    const loan = Loan.open(await this.loans.nextId(), isbn, member.id, new Date());
    await this.loans.save(loan);
    return loan;
  }
}

import type { Loan } from '../../domain/lending/Loan';
import type { LoanRepository } from '../ports/LoanRepository';

export class ListMemberLoansUseCase {
  constructor(private readonly loans: LoanRepository) {}

  async execute(memberId: string): Promise<Loan[]> {
    return this.loans.findOpenByMember(memberId);
  }
}

import { NotFoundError } from '../../domain/catalog/errors';
import type { Loan } from '../../domain/lending/Loan';
import type { LoanRepository } from '../ports/LoanRepository';

export class ReturnBookUseCase {
  constructor(private readonly loans: LoanRepository) {}

  async execute(loanId: string): Promise<Loan> {
    const loan = await this.loans.findById(loanId);
    if (loan === undefined) throw new NotFoundError(`loan ${loanId}`);
    loan.return(new Date());
    await this.loans.save(loan);
    return loan;
  }
}

import type { Isbn } from '../../domain/catalog/Isbn';
import type { Loan } from '../../domain/lending/Loan';

/** Outbound port: where loans are kept. */
export interface LoanRepository {
  nextId(): Promise<string>;
  save(loan: Loan): Promise<void>;
  findById(id: string): Promise<Loan | undefined>;
  findOpenByMember(memberId: string): Promise<Loan[]>;
  countOpenByIsbn(isbn: Isbn): Promise<number>;
  countOpenByMember(memberId: string): Promise<number>;
}

import { BookController } from '../adapters/inbound/http/BookController';
import { LoanController } from '../adapters/inbound/http/LoanController';
import { MemberController } from '../adapters/inbound/http/MemberController';
import { InMemoryBookRepository } from '../adapters/outbound/persistence/InMemoryBookRepository';
import { InMemoryLoanRepository } from '../adapters/outbound/persistence/InMemoryLoanRepository';
import { InMemoryMemberRepository } from '../adapters/outbound/persistence/InMemoryMemberRepository';
import { ListBooksUseCase } from '../application/catalog/ListBooksUseCase';
import { RegisterBookUseCase } from '../application/catalog/RegisterBookUseCase';
import { LendBookUseCase } from '../application/lending/LendBookUseCase';
import { ListMemberLoansUseCase } from '../application/lending/ListMemberLoansUseCase';
import { ReturnBookUseCase } from '../application/lending/ReturnBookUseCase';
import { GetMemberUseCase } from '../application/membership/GetMemberUseCase';
import { RegisterMemberUseCase } from '../application/membership/RegisterMemberUseCase';

/** Composition root: the only place that instantiates adapters. */
export function createContainer() {
  const books = new InMemoryBookRepository();
  const members = new InMemoryMemberRepository();
  const loans = new InMemoryLoanRepository();
  return {
    bookController: new BookController(new RegisterBookUseCase(books), new ListBooksUseCase(books)),
    memberController: new MemberController(new RegisterMemberUseCase(members), new GetMemberUseCase(members)),
    loanController: new LoanController(
      new LendBookUseCase(books, members, loans),
      new ReturnBookUseCase(loans),
      new ListMemberLoansUseCase(loans),
    ),
  };
}

export type Container = ReturnType<typeof createContainer>;

import { DomainError } from '../catalog/errors';
import type { Isbn } from '../catalog/Isbn';

export const LOAN_DAYS = 21;
const DAY_MS = 24 * 60 * 60 * 1000;

export class NoCopyAvailableError extends DomainError {
  constructor(isbn: string) {
    super('NO_COPY_AVAILABLE', `no copy of ${isbn} is available`);
  }
}

export class BorrowingLimitError extends DomainError {
  constructor(memberId: string, limit: number) {
    super('BORROWING_LIMIT', `member ${memberId} already has ${String(limit)} open loans`);
  }
}

export class AlreadyReturnedError extends DomainError {
  constructor(loanId: string) {
    super('ALREADY_RETURNED', `loan ${loanId} was already returned`);
  }
}

/** One copy of a book lent to one member. */
export class Loan {
  private constructor(
    readonly id: string,
    readonly isbn: Isbn,
    readonly memberId: string,
    readonly loanedAt: Date,
    readonly dueAt: Date,
    private returned: Date | undefined,
  ) {}

  static open(id: string, isbn: Isbn, memberId: string, at: Date): Loan {
    return new Loan(id, isbn, memberId, at, new Date(at.getTime() + LOAN_DAYS * DAY_MS), undefined);
  }

  get returnedAt(): Date | undefined {
    return this.returned;
  }

  get isOpen(): boolean {
    return this.returned === undefined;
  }

  return(at: Date): void {
    if (!this.isOpen) throw new AlreadyReturnedError(this.id);
    this.returned = at;
  }
}

