import type { OverdueReportUseCase } from '../../../application/reporting/OverdueReportUseCase';
import { errorResponse } from './http';
import type { HttpRequest, HttpResponse } from './http';

/** GET /reports/overdue?asOf=YYYY-MM-DD */
export class ReportController {
  constructor(private readonly overdueReport: OverdueReportUseCase) {}

  async overdue(req: HttpRequest): Promise<HttpResponse> {
    const asOf = req.query?.asOf;
    if (asOf !== undefined && !/^\d{4}-\d{2}-\d{2}$/.test(asOf)) {
      return { status: 400, body: { error: 'INVALID_DATE', message: 'asOf must be YYYY-MM-DD' } };
    }
    try {
      const lines = await this.overdueReport.execute(asOf === undefined ? undefined : new Date(`${asOf}T00:00:00Z`));
      return {
        status: 200,
        body: lines.map((l) => ({ ...l, dueAt: l.dueAt.toISOString().slice(0, 10) })),
      };
    } catch (err) {
      return errorResponse(err);
    }
  }
}

import type { LoanRepository } from '../../../application/ports/LoanRepository';
import type { OverdueLoansQuery } from '../../../application/ports/OverdueLoansQuery';
import type { Isbn } from '../../../domain/catalog/Isbn';
import type { Loan } from '../../../domain/lending/Loan';

export class InMemoryLoanRepository implements LoanRepository, OverdueLoansQuery {
  private readonly byId = new Map<string, Loan>();
  private seq = 0;

  async nextId(): Promise<string> {
    this.seq += 1;
    return `l-${String(this.seq)}`;
  }

  async save(loan: Loan): Promise<void> {
    this.byId.set(loan.id, loan);
  }

  async findById(id: string): Promise<Loan | undefined> {
    return this.byId.get(id);
  }

  async findOpenByMember(memberId: string): Promise<Loan[]> {
    return this.all().filter((l) => l.isOpen && l.memberId === memberId);
  }

  async countOpenByIsbn(isbn: Isbn): Promise<number> {
    return this.all().filter((l) => l.isOpen && l.isbn.value === isbn.value).length;
  }

  async countOpenByMember(memberId: string): Promise<number> {
    return (await this.findOpenByMember(memberId)).length;
  }

  async findOpenDueBefore(at: Date): Promise<Loan[]> {
    return this.all().filter((l) => l.isOpen && l.dueAt.getTime() < at.getTime());
  }

  private all(): Loan[] {
    return [...this.byId.values()];
  }
}

import type { Loan } from '../../domain/lending/Loan';

/** Outbound port, read side: open loans whose due date is before `at`. */
export interface OverdueLoansQuery {
  findOpenDueBefore(at: Date): Promise<Loan[]>;
}

import type { BookRepository } from '../ports/BookRepository';
import type { Clock } from '../ports/Clock';
import type { MemberRepository } from '../ports/MemberRepository';
import type { OverdueLoansQuery } from '../ports/OverdueLoansQuery';

const DAY_MS = 24 * 60 * 60 * 1000;

export interface OverdueLine {
  readonly isbn: string;
  readonly title: string;
  readonly memberName: string;
  readonly memberEmail: string;
  readonly dueAt: Date;
  readonly daysLate: number;
}

export class OverdueReportUseCase {
  constructor(
    private readonly overdueLoans: OverdueLoansQuery,
    private readonly books: BookRepository,
    private readonly members: MemberRepository,
    private readonly clock: Clock,
  ) {}

  async execute(asOf?: Date): Promise<OverdueLine[]> {
    const at = asOf ?? this.clock.now();
    const lines: OverdueLine[] = [];
    for (const loan of await this.overdueLoans.findOpenDueBefore(at)) {
      const book = await this.books.findByIsbn(loan.isbn);
      const member = await this.members.findById(loan.memberId);
      lines.push({
        isbn: loan.isbn.value,
        title: book?.title ?? '(unknown book)',
        memberName: member?.name ?? '(unknown member)',
        memberEmail: member?.email.value ?? '',
        dueAt: loan.dueAt,
        daysLate: Math.floor((at.getTime() - loan.dueAt.getTime()) / DAY_MS),
      });
    }
    return lines.sort((a, b) => b.daysLate - a.daysLate);
  }
}

import { BookController } from '../adapters/inbound/http/BookController';
import { LoanController } from '../adapters/inbound/http/LoanController';
import { MemberController } from '../adapters/inbound/http/MemberController';
import { ReportController } from '../adapters/inbound/http/ReportController';
import { InMemoryBookRepository } from '../adapters/outbound/persistence/InMemoryBookRepository';
import { InMemoryLoanRepository } from '../adapters/outbound/persistence/InMemoryLoanRepository';
