import type { Notifier } from '../../../application/ports/Notifier';

/** Prints mails instead of sending them; keeps them for inspection. */
export class ConsoleNotifier implements Notifier {
  readonly sent: { to: string; subject: string; body: string }[] = [];

  constructor(private readonly print: (line: string) => void = (line) => console.log(line)) {}

  async send(to: string, subject: string, body: string): Promise<void> {
    this.sent.push({ to, subject, body });
    this.print(`mail to ${to}: ${subject}`);
  }
}

import type { ReminderLog } from '../../../application/ports/ReminderLog';

export class InMemoryReminderLog implements ReminderLog {
  private readonly last = new Map<string, Date>();

  async lastSent(loanId: string): Promise<Date | undefined> {
    return this.last.get(loanId);
  }

  async record(loanId: string, at: Date): Promise<void> {
    this.last.set(loanId, at);
  }
}

import type { Clock } from '../../application/ports/Clock';
import type { SendOverdueRemindersUseCase } from '../../application/reminders/SendOverdueRemindersUseCase';

/** Time-driven inbound adapter: a scheduler calls runOnce() once a day. */
export class OverdueReminderJob {
  constructor(
    private readonly sendReminders: SendOverdueRemindersUseCase,
    private readonly clock: Clock,
  ) {}

  async runOnce(): Promise<string[]> {
    return this.sendReminders.execute(this.clock.now());
  }
}

/** Outbound port: deliver a message to a member. */
export interface Notifier {
  send(to: string, subject: string, body: string): Promise<void>;
}

/** Outbound port: when each loan was last reminded. */
export interface ReminderLog {
  lastSent(loanId: string): Promise<Date | undefined>;
  record(loanId: string, at: Date): Promise<void>;
}

import type { Notifier } from '../ports/Notifier';
import type { ReminderLog } from '../ports/ReminderLog';
import type { OverdueReportUseCase } from '../reporting/OverdueReportUseCase';

export const REMIND_EVERY_DAYS = 7;
const DAY_MS = 24 * 60 * 60 * 1000;

/** Sends one reminder per overdue loan, at most once every REMIND_EVERY_DAYS days. Returns the loans reminded. */
export class SendOverdueRemindersUseCase {
  constructor(
    private readonly overdueReport: OverdueReportUseCase,
    private readonly notifier: Notifier,
    private readonly log: ReminderLog,
  ) {}

  async execute(at: Date): Promise<string[]> {
    const sent: string[] = [];
    for (const line of await this.overdueReport.execute(at)) {
      const last = await this.log.lastSent(line.loanId);
      if (last !== undefined && at.getTime() - last.getTime() < REMIND_EVERY_DAYS * DAY_MS) continue;
      await this.notifier.send(
        line.memberEmail,
        `Overdue: ${line.title}`,
        `Dear ${line.memberName}, "${line.title}" was due on ${line.dueAt.toISOString().slice(0, 10)} and is ${String(line.daysLate)} day(s) late. Please return it.`,
      );
      await this.log.record(line.loanId, at);
      sent.push(line.loanId);
    }
    return sent;
  }
}

import type { BookRepository } from '../ports/BookRepository';
import type { Clock } from '../ports/Clock';
import type { MemberRepository } from '../ports/MemberRepository';
import type { OverdueLoansQuery } from '../ports/OverdueLoansQuery';

const DAY_MS = 24 * 60 * 60 * 1000;

export interface OverdueLine {
  readonly loanId: string;
  readonly isbn: string;
  readonly title: string;
  readonly memberName: string;
  readonly memberEmail: string;
  readonly dueAt: Date;
  readonly daysLate: number;
}

export class OverdueReportUseCase {
  constructor(
    private readonly overdueLoans: OverdueLoansQuery,
    private readonly books: BookRepository,
    private readonly members: MemberRepository,
    private readonly clock: Clock,
  ) {}

  async execute(asOf?: Date): Promise<OverdueLine[]> {
    const at = asOf ?? this.clock.now();
    const lines: OverdueLine[] = [];
    for (const loan of await this.overdueLoans.findOpenDueBefore(at)) {
      const book = await this.books.findByIsbn(loan.isbn);
      const member = await this.members.findById(loan.memberId);
      lines.push({
        loanId: loan.id,
        isbn: loan.isbn.value,
        title: book?.title ?? '(unknown book)',
        memberName: member?.name ?? '(unknown member)',
        memberEmail: member?.email.value ?? '',
        dueAt: loan.dueAt,
        daysLate: Math.floor((at.getTime() - loan.dueAt.getTime()) / DAY_MS),
      });
    }
    return lines.sort((a, b) => b.daysLate - a.daysLate);
  }
}

import { BookController } from '../adapters/inbound/http/BookController';
import { LoanController } from '../adapters/inbound/http/LoanController';
import { MemberController } from '../adapters/inbound/http/MemberController';
import { ReportController } from '../adapters/inbound/http/ReportController';
import { ConsoleNotifier } from '../adapters/outbound/notifications/ConsoleNotifier';
import { InMemoryReminderLog } from '../adapters/outbound/notifications/InMemoryReminderLog';
import { InMemoryBookRepository } from '../adapters/outbound/persistence/InMemoryBookRepository';
import { InMemoryLoanRepository } from '../adapters/outbound/persistence/InMemoryLoanRepository';
import { InMemoryMemberRepository } from '../adapters/outbound/persistence/InMemoryMemberRepository';
import { SystemClock } from '../adapters/outbound/time/SystemClock';
import { OverdueReminderJob } from '../adapters/scheduled/OverdueReminderJob';
import { ListBooksUseCase } from '../application/catalog/ListBooksUseCase';
import { RegisterBookUseCase } from '../application/catalog/RegisterBookUseCase';
import { LendBookUseCase } from '../application/lending/LendBookUseCase';
import { ListMemberLoansUseCase } from '../application/lending/ListMemberLoansUseCase';
import { ReturnBookUseCase } from '../application/lending/ReturnBookUseCase';
import { GetMemberUseCase } from '../application/membership/GetMemberUseCase';
import { RegisterMemberUseCase } from '../application/membership/RegisterMemberUseCase';
import type { Clock } from '../application/ports/Clock';
import type { Notifier } from '../application/ports/Notifier';
import { SendOverdueRemindersUseCase } from '../application/reminders/SendOverdueRemindersUseCase';
import { OverdueReportUseCase } from '../application/reporting/OverdueReportUseCase';

/** Composition root: the only place that instantiates adapters. */
export function createContainer(clock: Clock = new SystemClock(), notifier: Notifier = new ConsoleNotifier()) {
  const books = new InMemoryBookRepository();
  const members = new InMemoryMemberRepository();
  const loans = new InMemoryLoanRepository();
  const overdueReport = new OverdueReportUseCase(loans, books, members, clock);
  return {
    bookController: new BookController(new RegisterBookUseCase(books), new ListBooksUseCase(books)),
    memberController: new MemberController(new RegisterMemberUseCase(members), new GetMemberUseCase(members)),
    loanController: new LoanController(
      new LendBookUseCase(books, members, loans, clock),
      new ReturnBookUseCase(loans, clock),
      new ListMemberLoansUseCase(loans),
    ),
    reportController: new ReportController(overdueReport),
    overdueReminderJob: new OverdueReminderJob(
      new SendOverdueRemindersUseCase(overdueReport, notifier, new InMemoryReminderLog()),
      clock,
    ),
  };
}

export type Container = ReturnType<typeof createContainer>;

